{"cells":[{"cell_type":"code","source":"import os\nfrom fastapi import Depends, HTTPException, status\nfrom fastapi.security import OAuth2AuthorizationCodeBearer\nimport jwt\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\n# Entra ID Configuration\nTENANT_ID = os.getenv(\"TENANT_ID\")\nCLIENT_ID = os.getenv(\"CLIENT_ID\")\nJWKS_URL = f\"https://login.microsoftonline.com/{TENANT_ID}/discovery/v2.0/keys\"\n\noauth2_scheme = OAuth2AuthorizationCodeBearer(\n    authorizationUrl=f\"https://login.microsoftonline.com/{TENANT_ID}/oauth2/v2.0/authorize\",\n    tokenUrl=f\"https://login.microsoftonline.com/{TENANT_ID}/oauth2/v2.0/token\",\n)\n\nasync def get_current_user(token: str = Depends(oauth2_scheme)):\n    try:\n        # WARNING: Insecure. Production code MUST verify the JWT signature.\n        payload = jwt.decode(token, options={\"verify_signature\": False})\n\n        if payload.get(\"aud\") != CLIENT_ID:\n            raise HTTPException(\n                status_code=status.HTTP_401_UNAUTHORIZED,\n                detail=\"Invalid audience\",\n                headers={\"WWW-Authenticate\": \"Bearer\"},\n            )\n        return payload\n\n    except jwt.PyJWTError as e:\n        raise HTTPException(\n            status_code=status.HTTP_401_UNAUTHORIZED,\n            detail=f\"Invalid token: {e}\",\n            headers={\"WWW-Authenticate\": \"Bearer\"},\n        )","outputs":[],"execution_count":null,"metadata":{}}],"metadata":{"colab":{"from_bard":true},"kernelspec":{"display_name":"Python 3","name":"python3"}},"nbformat":4,"nbformat_minor":0}